import{_ as e,o,c as d,a2 as r}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"モデルプロバイダーとモデル","description":"","frontmatter":{},"headers":[],"relativePath":"ja/integrations/providers/llm.md","filePath":"ja/integrations/providers/llm.md","lastUpdated":1792323081000}'),a={name:"ja/integrations/providers/llm.md"};function i(n,t,l,c,s,h){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="モデルプロバイダーとモデル" tabindex="-1">モデルプロバイダーとモデル <a class="header-anchor" href="#モデルプロバイダーとモデル" aria-label="Permalink to &quot;モデルプロバイダーとモデル&quot;">​</a></h1><p>Memoh を日常的に使うには、たいてい次のものを設定します。</p><ul><li>1 つ以上の<strong>モデルプロバイダー</strong>（上流 API への接続方法）</li><li>その配下の<strong>モデル</strong></li><li>読み上げを使うなら <strong>音声合成</strong>（<strong>音声合成</strong> 設定ページを参照）</li><li>音声をテキストに変換するなら <strong>文字起こし</strong></li></ul><p>チャットと embedding は <strong>Models</strong> ページで管理します。音声合成モデルは TTS のフローで別に扱い、文字起こしモデルは文字起こし設定ページで管理します。</p><hr><h2 id="モデルプロバイダーの基本" tabindex="-1">モデルプロバイダーの基本 <a class="header-anchor" href="#モデルプロバイダーの基本" aria-label="Permalink to &quot;モデルプロバイダーの基本&quot;">​</a></h2><p><strong>モデルプロバイダー</strong>には、ある上流サービスへの接続方法が保存されます。例えば次のとおりです。</p><ul><li>プロトコル（<code>client_type</code>）</li><li>必要な場合の base URL</li><li>API Key や OAuth などの認証情報</li></ul><p>よくあるのは OpenAI 互換エンドポイント、Anthropic、Google、Codex、GitHub Copilot などです。</p><h3 id="モデルプロバイダーの新規作成" tabindex="-1">モデルプロバイダーの新規作成 <a class="header-anchor" href="#モデルプロバイダーの新規作成" aria-label="Permalink to &quot;モデルプロバイダーの新規作成&quot;">​</a></h3><p>モデルプロバイダーは現在、<strong>テンプレートカタログ</strong>から作成します。テンプレートには適切な client type、base URL、厳選されたモデル一覧が含まれているので、通常は API Key を入力するだけで済みます。</p><ol><li>サイドバーから <strong>Models</strong> を開きます。</li><li><strong>Add Provider</strong> をクリックし、テンプレート一覧から選びます——まだ設定していないものだけが表示され、検索もできます（ローカライズされたベンダー名でも検索できます）。</li><li>テンプレートが求める認証情報を入力します。</li><li>保存します。モデルプロバイダーとそのプリセットモデルは、保存時に一緒に生成されます。</li></ol><p>内蔵テンプレートには OpenAI、Anthropic、Google、OpenRouter、DeepSeek、<strong>Zhipu AI（bigmodel.cn）</strong>、Z.AI、Azure OpenAI、Cerebras、Cloudflare、Fireworks、Perplexity、Together などがあります。<strong>Zhipu AI</strong>（<code>open.bigmodel.cn</code>、中国本土アカウント）と <strong>Z.AI</strong>（<code>api.z.ai</code>、国際アカウント）は、別のテンプレート・別の key 体系であることに注意してください——key がどちらで発行されたかに合わせて選びます。</p><p>合うテンプレートがない場合でも、完全にカスタムなモデルプロバイダーを作成できます。</p><p>よく使うフィールド：</p><table tabindex="0"><thead><tr><th>フィールド</th><th>説明</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>表示名。例: <code>OpenAI</code>。</td></tr><tr><td><strong>Client Type</strong></td><td>このモデルプロバイダーが使うプロトコル。</td></tr><tr><td><strong>Base URL</strong></td><td>一部のプロトコルで必須となるルート URL。</td></tr><tr><td><strong>API Key</strong></td><td>キー認証の場合に入力します。</td></tr></tbody></table><h3 id="クライアントタイプ" tabindex="-1">クライアントタイプ <a class="header-anchor" href="#クライアントタイプ" aria-label="Permalink to &quot;クライアントタイプ&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Client Type</th><th>主な用途</th></tr></thead><tbody><tr><td><code>openai-responses</code></td><td>OpenAI Responses スタイル</td></tr><tr><td><code>openai-completions</code></td><td>Chat Completions 互換</td></tr><tr><td><code>anthropic-messages</code></td><td>Anthropic Messages</td></tr><tr><td><code>google-generative-ai</code></td><td>Google Gemini</td></tr><tr><td><code>openai-codex</code></td><td>Codex / ChatGPT 系、OAuth</td></tr><tr><td><code>github-copilot</code></td><td>Copilot、デバイスコード OAuth</td></tr><tr><td><code>edge-speech</code></td><td>Edge 読み上げ</td></tr><tr><td><code>openai-speech</code></td><td>OpenAI 互換の音声合成</td></tr><tr><td><code>openai-transcription</code></td><td>OpenAI 互換の文字起こし</td></tr><tr><td><code>openrouter-speech</code></td><td>OpenRouter 音声合成</td></tr><tr><td><code>openrouter-transcription</code></td><td>OpenRouter 文字起こし</td></tr><tr><td><code>elevenlabs-speech</code></td><td>ElevenLabs 音声合成</td></tr><tr><td><code>elevenlabs-transcription</code></td><td>ElevenLabs 文字起こし</td></tr><tr><td><code>deepgram-speech</code></td><td>Deepgram 音声合成</td></tr><tr><td><code>deepgram-transcription</code></td><td>Deepgram 文字起こし</td></tr><tr><td><code>minimax-speech</code></td><td>MiniMax 音声合成</td></tr><tr><td><code>volcengine-speech</code></td><td>Volcengine 音声合成</td></tr><tr><td><code>alibabacloud-speech</code></td><td>Alibaba Cloud 音声合成</td></tr><tr><td><code>microsoft-speech</code></td><td>Microsoft 音声合成</td></tr><tr><td><code>google-transcription</code></td><td>Google 文字起こし</td></tr></tbody></table><p>音声合成と文字起こしのタイプは、メインのチャット用には使えません。音声合成は <strong>音声合成</strong> 設定ページ、文字起こしは文字起こし設定ページで設定します。利用できるモデル・ボイス・言語は、provider テンプレートと上流アカウントによって異なります。</p><hr><h2 id="oauth-を使うモデルプロバイダー" tabindex="-1">OAuth を使うモデルプロバイダー <a class="header-anchor" href="#oauth-を使うモデルプロバイダー" aria-label="Permalink to &quot;OAuth を使うモデルプロバイダー&quot;">​</a></h2><p>ほとんどのタイプは通常の API Key を使います。例外は <code>openai-codex</code> と <code>github-copilot</code> です——どちらも同じフローの<strong>デバイスコード認証</strong>を使い、API Key の入力欄はありません。</p><ol><li>まずモデルプロバイダーを作成して<strong>保存</strong>します——認証の入り口は、保存済みモデルプロバイダーの詳細パネルにしかありません。</li><li><strong>Account</strong> セクションで <strong>Connect</strong> をクリックすると、確認用 URL、ワンタイムのユーザーコード、有効期限のカウントダウンが表示されます。</li><li><strong>Copy &amp; Open</strong> をクリックして確認ページでコードを入力すれば、残りは Memoh が自動で完了させます。</li></ol><blockquote><p>ワンタイムコードは、表示された公式の確認 URL でのみ入力してください——デバイスコードはフィッシングに悪用されることがあります。</p></blockquote><p>接続後はモデルプロバイダー上に現在のアカウントが表示され、<strong>Revoke</strong> で切断できます。</p><h3 id="openai-codex" tabindex="-1">OpenAI Codex <a class="header-anchor" href="#openai-codex" aria-label="Permalink to &quot;OpenAI Codex&quot;">​</a></h3><ul><li>タイプは <code>openai-codex</code> で、テンプレートは <code>https://chatgpt.com/backend-api</code> を指します</li><li>ChatGPT アカウントでサインインします</li></ul><p>コーディング寄りで、Codex 系のワークフローを使いたい場合に適しています。</p><h3 id="github-copilot" tabindex="-1">GitHub Copilot <a class="header-anchor" href="#github-copilot" aria-label="Permalink to &quot;GitHub Copilot&quot;">​</a></h3><ul><li>タイプは <code>github-copilot</code></li><li>GitHub アカウントでサインインします</li></ul><p>すでに Copilot を持っているなら、それを Memoh でも再利用できます。</p><div class="warning custom-block"><p class="custom-block-title">アップグレードに関する注意</p><p>Copilot の認証情報は以前はユーザー単位で保存されていましたが、現在は Codex と同じく、モデルプロバイダー単位の 1 件になりました。既存のデプロイをアップグレードした後は、Copilot のモデルプロバイダーを<strong>一度再認証</strong>してください。</p></div><h3 id="マネージドモデルカタログ" tabindex="-1">マネージドモデルカタログ <a class="header-anchor" href="#マネージドモデルカタログ" aria-label="Permalink to &quot;マネージドモデルカタログ&quot;">​</a></h3><p>2 つの OAuth モデルプロバイダーのモデル一覧は、どちらも上流からリアルタイムに取得される<strong>マネージドカタログ</strong>です（Codex にはそもそも静的なモデル一覧がなく、常にあなたの ChatGPT アカウントで実際に使えるものを反映します）。</p><ul><li>デバイス認証の完了後にカタログは自動同期され、その後もいつでも再インポートできます。</li><li>上流のカタログから消えたモデルは利用不可としてマークされるだけで、削除はされません。</li><li>再インポートは増分マージです。新しく検出された機能が補完され、自分のモデル設定は上書きされません。</li></ul><hr><h2 id="モデルのインポート" tabindex="-1">モデルのインポート <a class="header-anchor" href="#モデルのインポート" aria-label="Permalink to &quot;モデルのインポート&quot;">​</a></h2><p>モデルプロバイダーを作成したら、その配下にモデルをインポートしたり手動で追加したりできます。</p><p>典型的な流れ：</p><ol><li>モデルプロバイダーを選択します。</li><li>モデルカタログを取得できるプロバイダーなら、<strong>Import Models</strong> をクリックします。</li><li>Memoh に保存したいモデルにチェックを入れます。</li></ol><p>上流のモデル ID が分かっている場合は、手動で追加することもできます。</p><h3 id="モデルの有効化スイッチ" tabindex="-1">モデルの有効化スイッチ <a class="header-anchor" href="#モデルの有効化スイッチ" aria-label="Permalink to &quot;モデルの有効化スイッチ&quot;">​</a></h3><p>モデルプロバイダーの詳細ページではモデルが 1 行ずつ並び、それぞれに<strong>有効化スイッチ</strong>があります。無効にしたモデルは再び有効化できるようこのページに残りますが、すべてのモデルセレクター（Bot 設定、チャット、embedding など）からは表示されなくなります。</p><p>デフォルト値は、モデルの追加のされ方によって異なります。</p><ul><li><strong>手動</strong>で追加したモデルは、デフォルトで有効です。</li><li><strong>一括インポート</strong>したモデルは、デフォルトで<strong>無効</strong>です——大きなカタログをインポートしてもセレクターがあふれないようにするためで、使いたいものだけ自分で有効にします。</li></ul><hr><h2 id="モデルタイプ" tabindex="-1">モデルタイプ <a class="header-anchor" href="#モデルタイプ" aria-label="Permalink to &quot;モデルタイプ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>タイプ</th><th>用途</th></tr></thead><tbody><tr><td><code>chat</code></td><td>会話、ツール、推論、画像生成など</td></tr><tr><td><code>embedding</code></td><td>ベクトル化、メモリ検索</td></tr><tr><td><code>speech</code></td><td>読み上げ。TTS で使用</td></tr><tr><td><code>transcription</code></td><td>音声からテキストへの変換。文字起こしで使用</td></tr></tbody></table><p><strong>Models</strong> ページで主に管理するのは chat / embedding です。speech は <strong>音声合成</strong> 設定ページ、transcription は文字起こし設定ページで扱います。</p><hr><h2 id="チャットモデルで注意すべき項目" tabindex="-1">チャットモデルで注意すべき項目 <a class="header-anchor" href="#チャットモデルで注意すべき項目" aria-label="Permalink to &quot;チャットモデルで注意すべき項目&quot;">​</a></h2><table tabindex="0"><thead><tr><th>フィールド</th><th>説明</th></tr></thead><tbody><tr><td><strong>Model ID</strong></td><td>上流の実際の id。例: <code>gpt-4o</code>。</td></tr><tr><td><strong>Name</strong></td><td>UI に表示される名前。</td></tr><tr><td><strong>Description</strong></td><td>任意の説明テキスト。モデル一覧ではホバーで表示され、セレクターでは検索対象にもなります。</td></tr><tr><td><strong>Compatibilities</strong></td><td><code>vision</code>、<code>tool-call</code>、<code>image-output</code>、<code>reasoning</code> など。</td></tr><tr><td><strong>Context Window</strong></td><td>おおよそのコンテキスト上限。</td></tr></tbody></table><h3 id="互換性" tabindex="-1">互換性 <a class="header-anchor" href="#互換性" aria-label="Permalink to &quot;互換性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>フラグ</th><th>意味</th></tr></thead><tbody><tr><td><code>vision</code></td><td>画像を入力できる</td></tr><tr><td><code>tool-call</code></td><td>ツールを呼び出せる</td></tr><tr><td><code>image-output</code></td><td>画像を生成できる</td></tr><tr><td><code>reasoning</code></td><td>明示的な推論モード／エフォート段階がある</td></tr></tbody></table><p>推論に対応している場合は、<code>reasoning_efforts</code>（<code>none</code>、<code>low</code>…<code>xhigh</code> など）を持つこともあります。</p><h3 id="context-window" tabindex="-1"><code>context_window</code> <a class="header-anchor" href="#context-window" aria-label="Permalink to &quot;`context_window`&quot;">​</a></h3><p>Memoh は次の用途に使います。</p><ul><li>アプリ上で、現在のセッションがどれだけコンテキストを使っているかを計算する</li><li><code>/status</code> などの表示を支える</li><li>上限に近づいているかを判断する</li><li>いつ <a href="./../../guides/compaction.html">コンテキスト圧縮</a> が必要になるかを決める</li></ul><p>未設定でも使えますが、<strong>使用率のパーセンテージ</strong>を正確に表示できなくなります。</p><h3 id="画像生成モデル" tabindex="-1">画像生成モデル <a class="header-anchor" href="#画像生成モデル" aria-label="Permalink to &quot;画像生成モデル&quot;">​</a></h3><p>Bot には <strong>Image Generation Model</strong> を個別に割り当てられます。<code>image-output</code> を持つ chat モデルである必要があります。必要に応じて、デフォルトのチャットモデルとは分けられます。</p><hr><h2 id="embedding-モデル" tabindex="-1">Embedding モデル <a class="header-anchor" href="#embedding-モデル" aria-label="Permalink to &quot;Embedding モデル&quot;">​</a></h2><p>Embedding モデルは、セマンティックなインデックス作成と検索に使われます。</p><p>必須フィールド：</p><table tabindex="0"><thead><tr><th>フィールド</th><th>説明</th></tr></thead><tbody><tr><td><strong>Dimensions</strong></td><td>embedding 出力のベクトル次元数。例: <code>1536</code>。</td></tr></tbody></table><p>メモリプロバイダーや、ベクトル検索に依存するあらゆる機能と組み合わせて使います。</p><hr><h2 id="音声合成と文字起こしのモデル" tabindex="-1">音声合成と文字起こしのモデル <a class="header-anchor" href="#音声合成と文字起こしのモデル" aria-label="Permalink to &quot;音声合成と文字起こしのモデル&quot;">​</a></h2><p>音声合成は <strong>音声合成</strong> 設定ページで設定し、通常の chat モデルプロバイダーのフローとは分かれています。現在の音声合成カテゴリーは次のとおりです。</p><ul><li>Edge：<code>edge-speech</code></li><li>OpenAI 互換：<code>openai-speech</code></li><li>OpenRouter：<code>openrouter-speech</code></li><li>ElevenLabs：<code>elevenlabs-speech</code></li><li>Deepgram：<code>deepgram-speech</code></li><li>MiniMax：<code>minimax-speech</code></li><li>Volcengine：<code>volcengine-speech</code></li><li>Alibaba Cloud：<code>alibabacloud-speech</code></li><li>Microsoft：<code>microsoft-speech</code></li></ul><p>文字起こしは文字起こし設定ページで設定します。現在の文字起こしカテゴリーは次のとおりです。</p><ul><li>OpenAI 互換：<code>openai-transcription</code></li><li>OpenRouter：<code>openrouter-transcription</code></li><li>ElevenLabs：<code>elevenlabs-transcription</code></li><li>Deepgram：<code>deepgram-transcription</code></li><li>Google：<code>google-transcription</code></li></ul><p>音声系モデルには provider 固有のボイス・フォーマット・話速・ピッチ・言語・認識の設定があり、chat / embedding とは別系統の設定です。</p><hr><h2 id="シンプルな考え方" tabindex="-1">シンプルな考え方 <a class="header-anchor" href="#シンプルな考え方" aria-label="Permalink to &quot;シンプルな考え方&quot;">​</a></h2><p>ほとんどの Bot では、いくつかの系統に分けて考えられます。</p><ul><li><strong>Chat</strong>：日常の会話</li><li><strong>Embedding</strong>：メモリ</li><li><strong>Speech / Transcription / 画像生成モデル</strong>：補助的な機能</li></ul><p>1 つのモデルに無理やりすべてを任せる必要はありません。</p><hr><h2 id="次のステップ" tabindex="-1">次のステップ <a class="header-anchor" href="#次のステップ" aria-label="Permalink to &quot;次のステップ&quot;">​</a></h2><ul><li>チャット・画像生成・メモリ・読み上げなどを Bot に割り当てる：<a href="./../../guides/working-with-bots.html">Bot</a></li><li>音声プロバイダーと音声モデルを設定する：<strong>音声合成</strong> 設定ページ</li><li>音声からテキストへの変換を設定する：クライアントの文字起こし設定ページを開く</li></ul>',82)])])}const b=e(a,[["render",i]]);export{g as __pageData,b as default};
